    common = set(x for row in left for x in row) & set(x for row in right for x in row)
    counts = {x: sum(row.count(x) for row in left + right) for x in common}
    bg = max(counts, key=counts.get)

    return [
        [2 if left[r][c] != bg or right[r][c] != bg else 3
         for c in range(n)]
