    left_w = sep
    right_w = w - sep - 1
    n = min(left_w, right_w)

    left_colors = {grid[r][c] for r in range(h) for c in range(left_w)}
    right_colors = {grid[r][c] for r in range(h) for c in range(sep + 1, w)}
    shared = left_colors & right_colors
    color = next(iter(shared))

    return [
        [
            3 if grid[r][c] == color and grid[r][sep + 1 + c] == color else color
            for c in range(n)
        ]
        for r in range(h)
    ]
